package local.skyfamily;
import android.graphics.*;import android.view.*;import android.widget.*;import java.util.*;
final class PdfMarkup extends FrameLayout {
 final PdfPane pane;final HashMap<Integer,StudyInk.Model> pages=new HashMap<>();Bitmap last;int displayed=-1,tool=0;boolean touching=false;PdfMarkup(PdfPane p){super(p.host);pane=p;setWillNotDraw(false);addView(p.image,new FrameLayout.LayoutParams(-1,-1));setContentDescription("Temporary PDF ink overlay. Marks are not saved or exported.");}
 RectF bounds(){Bitmap b=pane.image.bitmap;if(b==null)return new RectF();float factor=Math.min(getWidth()/(float)b.getWidth(),getHeight()/(float)b.getHeight())*pane.image.zoom;float w=b.getWidth()*factor,h=b.getHeight()*factor;return new RectF((getWidth()-w)/2+pane.image.panX,(getHeight()-h)/2+pane.image.panY,(getWidth()+w)/2+pane.image.panX,(getHeight()+h)/2+pane.image.panY);}
 boolean ready(){return pane.image.bitmap!=null&&displayed==pane.page&&!pane.status.getText().toString().startsWith("Rendering")&&!pane.closed;}
 protected void dispatchDraw(Canvas c){super.dispatchDraw(c);if(last!=pane.image.bitmap){last=pane.image.bitmap;if(last!=null)displayed=pane.page;}if(ready()){StudyInk.Model m=pages.get(displayed);if(m!=null)m.draw(c,bounds());}}
 public boolean onInterceptTouchEvent(MotionEvent e){return tool!=0&&ready()&&bounds().contains(e.getX(),e.getY());}
 public boolean onTouchEvent(MotionEvent e){if(tool==0||!ready())return false;int action=e.getActionMasked();StudyInk.Model m=pages.get(displayed);if(e.getPointerCount()>1){if(m!=null)m.cancel();touching=false;invalidate();return true;}RectF b=bounds();if(action==MotionEvent.ACTION_DOWN){if(m==null){if(pages.size()>=100){pane.host.toast("Temporary markup limit reached");return true;}m=new StudyInk.Model();pages.put(displayed,m);}touching=m.begin((e.getX()-b.left)/b.width(),(e.getY()-b.top)/b.height(),tool==2?0x66ffcf33:0xff245cb3,tool==2?22:4);if(!touching)pane.host.toast("Ink limit reached for this page");}else if(action==MotionEvent.ACTION_MOVE&&touching&&m!=null)m.add((e.getX()-b.left)/b.width(),(e.getY()-b.top)/b.height());else if(action==MotionEvent.ACTION_UP){if(m!=null)m.end();touching=false;performClick();}else if(action==MotionEvent.ACTION_CANCEL){if(m!=null)m.cancel();touching=false;}invalidate();return true;}public boolean performClick(){super.performClick();return true;}void undo(){StudyInk.Model m=pages.get(displayed);if(m!=null)m.undo();invalidate();}void clearPage(){pages.remove(displayed);invalidate();}
}
